// This code:
// 1. Parses the AI output stored in the "output" field.
// 2. Separates every section into its own JSON field automatically.
// 3. Keeps the original Campaign Breakdown section intact.
// 4. Removes the campaign_breakdown_items output entirely.
// 5. Works even if sections are added, removed, or renamed.

const text = $json.output;

const result = {};

// Extract all sections dynamically
const sectionRegex = /([A-Za-z ]+):\n([\s\S]*?)(?=\n\n[A-Za-z ]+:\n|$)/g;

let match;

while ((match = sectionRegex.exec(text)) !== null) {
  const key = match[1]
    .trim()
    .toLowerCase()
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, "_");

  const value = match[2].trim();

  result[key] = value;
}

return [
  {
    json: result,
  },
];

// This code:
// 1. Gets today's date.
// 2. Finds the Monday and Friday of the PREVIOUS week.
// 3. Formats both dates as DD/MM/YYYY.
// 4. Also includes today's date.
// 5. Returns:
//    - Previous Week Range
//    - Present Day
//
// Example Output:
// {
//   "Previous Week Range": "29/06/2026 - 03/07/2026",
//   "Present Day": "11/07/2026"
// }

const today = new Date();

// Get current day of week (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
const currentDay = today.getDay();

// Calculate how many days have passed since Monday
const daysSinceMonday = currentDay === 0 ? 6 : currentDay - 1;

// Get previous week's Monday
const previousMonday = new Date(today);
previousMonday.setDate(today.getDate() - daysSinceMonday - 7);

// Get previous week's Friday
const previousFriday = new Date(previousMonday);
previousFriday.setDate(previousMonday.getDate() + 6);

// Format function: DD/MM/YYYY
const formatDate = (date) => {
  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const year = date.getFullYear();

  return `${day}/${month}/${year}`;
};

return [
  {
    json: {
      "Previous Week Range": `${formatDate(previousMonday)} - ${formatDate(previousFriday)}`,
      "Present Day": formatDate(today)
    }
  }
];

// This code:
// 1. Takes one or multiple campaign records as input.
// 2. Calculates overall campaign totals.
// 3. Calculates average CTR, CPC, Conversion Rate, and ROAS.
// 4. Returns ONLY the campaign summary.
// 5. Works whether there is 1 campaign or many campaigns.

const channelsCovered = [];

let totalImpressions = 0;
let totalClicks = 0;
let totalConversions = 0;
let totalSpend = 0;
let totalRevenue = 0;

let totalCTR = 0;
let totalCPC = 0;
let totalConversionRate = 0;
let totalROAS = 0;

const items = $input.all();

items.forEach(item => {
  const channel = item.json["Channel"];

  const impressions = Number(item.json["Impressions"]) || 0;
  const clicks = Number(item.json["Clicks"]) || 0;
  const conversions = Number(item.json["Conversions"]) || 0;
  const spend = Number(item.json["Spend"]) || 0;
  const revenue = Number(item.json["Revenue"]) || 0;

  // Calculate campaign metrics
  const ctr = impressions > 0
    ? ((clicks / impressions) * 100)
    : 0;

  const cpc = clicks > 0
    ? (spend / clicks)
    : 0;

  const conversionRate = clicks > 0
    ? ((conversions / clicks) * 100)
    : 0;

  const roas = spend > 0
    ? (revenue / spend)
    : 0;

  // Accumulate totals
  totalImpressions += impressions;
  totalClicks += clicks;
  totalConversions += conversions;
  totalSpend += spend;
  totalRevenue += revenue;

  // Accumulate averages
  totalCTR += ctr;
  totalCPC += cpc;
  totalConversionRate += conversionRate;
  totalROAS += roas;

  // Track unique channels
  if (!channelsCovered.includes(channel)) {
    channelsCovered.push(channel);
  }
});

const totalCampaigns = items.length;

return [
  {
    json: {
      campaign_summary: {
        "Total Campaigns": totalCampaigns,
        "Channels Covered": channelsCovered.join(", "),
        "Total Impressions": totalImpressions,
        "Total Clicks": totalClicks,
        "Total Conversions": totalConversions,
        "Total Spend": totalSpend,
        "Total Revenue": totalRevenue,
        "Average CTR": totalCampaigns > 0
          ? Number((totalCTR / totalCampaigns).toFixed(2))
          : 0,
        "Average CPC": totalCampaigns > 0
          ? Number((totalCPC / totalCampaigns).toFixed(2))
          : 0,
        "Average Conversion Rate": totalCampaigns > 0
          ? Number((totalConversionRate / totalCampaigns).toFixed(2))
          : 0,
        "Average ROAS": totalCampaigns > 0
          ? Number((totalROAS / totalCampaigns).toFixed(2))
          : 0,
      }
    }
  }
];

